/**
 * TOTP (RFC 6238) — the six-digit code an authenticator app shows.
 *
 * WHY THIS EXISTS. Groww's trading API offers three ways to authenticate, and
 * only one of them works for something that trades without a human present:
 *
 *   access token      generated by hand, EXPIRES DAILY AT 06:00
 *   API key + secret  needs a click on Groww's key page every day
 *   API key + TOTP    a code derived from a shared secret — no daily click
 *
 * The first two mean someone must log in before 09:15 every single morning or
 * the bot silently does nothing. So the secret is stored once and the code is
 * derived here, which is exactly what the authenticator app on a phone does.
 *
 * Implemented rather than pulled from npm because the algorithm is forty lines
 * of well-specified arithmetic, it is easy to test against the RFC's published
 * vectors, and a dependency that can generate credentials is a dependency worth
 * not having.
 *
 * SECURITY. The secret is equivalent to the second factor itself. It belongs in
 * `.env` (git-ignored), never in code, and never in a log line.
 */

import { createHmac } from 'node:crypto';

/** RFC 4648 base32, which is how every authenticator app hands out a secret. */
export function base32Decode(input: string): Buffer {
  const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  // Padding and spacing are cosmetic — Groww, Google and Authy all format
  // secrets differently and every one of them must decode to the same bytes.
  const clean = input.toUpperCase().replace(/[\s=-]/g, '');
  if (!clean.length) throw new Error('TOTP secret is empty');

  let bits = 0;
  let value = 0;
  const out: number[] = [];
  for (const ch of clean) {
    const idx = ALPHABET.indexOf(ch);
    if (idx < 0) throw new Error(`TOTP secret contains a non-base32 character: ${ch}`);
    value = (value << 5) | idx;
    bits += 5;
    if (bits >= 8) {
      bits -= 8;
      out.push((value >>> bits) & 0xff);
    }
  }
  return Buffer.from(out);
}

export interface TotpOptions {
  /** Seconds per code. Thirty everywhere in practice. */
  step?: number;
  digits?: number;
  algorithm?: 'sha1' | 'sha256' | 'sha512';
}

/**
 * The code for a given instant. `now` is milliseconds since the epoch, taken as
 * an argument rather than read from the clock so this stays pure and testable.
 */
export function totp(secret: string, now: number = Date.now(), opts: TotpOptions = {}): string {
  const { step = 30, digits = 6, algorithm = 'sha1' } = opts;
  const counter = Math.floor(now / 1000 / step);

  // The counter is a big-endian 64-bit integer. JavaScript bitwise operators
  // are 32-bit, so the high half is written through BigInt rather than shifts.
  const buf = Buffer.alloc(8);
  buf.writeBigUInt64BE(BigInt(counter));

  const hmac = createHmac(algorithm, base32Decode(secret)).update(buf).digest();
  // Dynamic truncation: the low nibble of the last byte picks the offset.
  const offset = hmac[hmac.length - 1] & 0x0f;
  const code =
    ((hmac[offset] & 0x7f) << 24) |
    ((hmac[offset + 1] & 0xff) << 16) |
    ((hmac[offset + 2] & 0xff) << 8) |
    (hmac[offset + 3] & 0xff);

  return String(code % 10 ** digits).padStart(digits, '0');
}

/**
 * Seconds until the current code expires.
 *
 * Used to avoid authenticating in the last moment of a window: a code fetched
 * with one second left can easily be stale by the time the request lands, and
 * the failure looks like bad credentials rather than bad timing.
 */
export function secondsRemaining(now: number = Date.now(), step = 30): number {
  return step - Math.floor(now / 1000) % step;
}
